/** A handover offer was refused. `reason` is the stable machine code. */
export class OwnershipHandoverError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: OwnershipHandoverRefusal) {
    super(`Ownership handover refused: ${reason}`);
    this.name = "OwnershipHandoverError";
