  payload: TaskflowEventMap["organization.ownership_transferred"],
): Promise<void> {
  return record(payload.orgId, "organization.ownership_transferred", {
    actorId: payload.actorId,
    subjectKind: "organization",
    subjectId: payload.orgId,
    projectId: null,
    summary: `Transferred ownership from ${payload.fromUserId} to ${payload.toUserId}`,
    metadata: {
      fromUserId: payload.fromUserId,
      toUserId: payload.toUserId,
