/**
 * Workspace ownership handover: offer, accept, decline, withdraw, lapse.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { OwnershipHandoverError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { NotFoundError } from "@/server/services/_support";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import { listActivity } from "@/server/services/activity-service";
import { changePlan } from "@/server/services/billing-service";
import { removeMember, resolveActor, updateMemberRole } from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import {
  acceptOwnershipHandover,
  cancelOwnershipHandover,
  declineOwnershipHandover,
  getPendingOwnershipHandover,
  initiateOwnershipHandover,
} from "@/server/services/organization-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
});

const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

async function offered(tenant: Tenant, to: "admin" | "member" | "viewer" = "member") {
  return initiateOwnershipHandover(
    tenant.actors.owner,
    tenant.org.id,
    tenant.userIds[to],
  );
}

describe("ownership handover", () => {
  it("offers to an active member and tells only them", async () => {
    const tenant = await createTenant("handover-offer", "growth");
    const offer = await offered(tenant);

    expect(offer).toMatchObject({
      orgId: tenant.org.id,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.member,
      status: "pending",
      resolvedAt: null,
    });
    expect(new Date(offer.expiresAt).getTime() - new Date(offer.createdAt).getTime()).toBe(
      WEEK_MS,
    );

    const pending = await getPendingOwnershipHandover(
      tenant.actors.viewer,
      tenant.org.id,
    );
    expect(pending?.id).toBe(offer.id);

    const forOfferee = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.member,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(forOfferee.items.map((row) => row.kind)).toContain("ownership_handover");

    const forOwner = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
