  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const offer = await requireOffereeOffer(actor, orgId);
  const accepter = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );
  const previous = await memberRepo.findMember(orgId, org.ownerId);
  const stamp = toIsoTimestamp(new Date());

  const resolved = await handoverRepo.resolveOwnershipHandover(
    offer.id,
    orgId,
    "accepted",
    stamp,
  );
  if (!resolved) throw new OwnershipHandoverError("nothing_pending");

  const roleChanges: Array<{ memberId: MemberId; from: Role; to: Role }> = [];

  // Promote first so the workspace never spends an instant with no owner.
  if (accepter.role !== "owner") {
    await memberRepo.updateMemberRole(orgId, accepter.id, "owner");
    roleChanges.push({ memberId: accepter.id, from: accepter.role, to: "owner" });
  }

  await orgRepo.updateOrgOwner(orgId, actor.userId);

  if (
    previous &&
    previous.id !== accepter.id &&
    previous.role === "owner"
  ) {
    await memberRepo.updateMemberRole(orgId, previous.id, "admin");
    roleChanges.push({ memberId: previous.id, from: "owner", to: "admin" });
  }

  ensureOwnershipTransferAudit();

  for (const change of roleChanges) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: change.memberId,
      from: change.from,
      to: change.to,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: org.ownerId,
    toUserId: actor.userId,
  });

  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const offer = await requireOffereeOffer(actor, orgId);
  const resolved = await handoverRepo.resolveOwnershipHandover(
    offer.id,
    orgId,
    "declined",
    toIsoTimestamp(new Date()),
  );
  if (!resolved) throw new OwnershipHandoverError("nothing_pending");
  return resolved;
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  const open = await handoverRepo.findOpenOwnershipHandover(
    orgId,
    toIsoTimestamp(new Date()),
  );
  if (!open) throw new OwnershipHandoverError("nothing_pending");

  const resolved = await handoverRepo.resolveOwnershipHandover(
    open.id,
    orgId,
    "canceled",
    toIsoTimestamp(new Date()),
  );
  if (!resolved) throw new OwnershipHandoverError("nothing_pending");
  return resolved;
}
