 * Open and resolved ownership offers. An offer stays `pending` until it is
 * accepted, declined, withdrawn, or observed to have lapsed.
 */
import { and, desc, eq, gt, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import type { OwnershipHandoverRow } from "@/server/db/schema/ownership-handovers";
import { brandId, brandStamp, brandStampOrNull } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

function toOwnershipHandover(row: OwnershipHandoverRow): OwnershipHandover {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    fromUserId: brandId<UserId>(row.fromUserId),
    toUserId: brandId<UserId>(row.toUserId),
    status: row.status,
    expiresAt: brandStamp(row.expiresAt),
    createdAt: brandStamp(row.createdAt),
    resolvedAt: brandStampOrNull(row.resolvedAt),
  };
}

export async function insertOwnershipHandover(input: {
  orgId: OrgId;
  fromUserId: UserId;
  toUserId: UserId;
  expiresAt: IsoTimestamp;
  createdAt: IsoTimestamp;
}): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId: input.orgId,
      fromUserId: input.fromUserId,
      toUserId: input.toUserId,
      status: "pending",
      expiresAt: input.expiresAt,
      createdAt: input.createdAt,
      resolvedAt: null,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/** The newest still-open offer: pending and strictly before its expiry. */
export async function findOpenOwnershipHandover(
  orgId: OrgId,
  at: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, at),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt), desc(ownershipHandovers.id))
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/** Newest pending row, including one whose expiry has already passed. */
export async function findLatestPendingOwnershipHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt), desc(ownershipHandovers.id))
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/**
 * Moves a still-pending offer to a terminal status. Returns null when the row
 * was already resolved, so two actors cannot both accept it.
 */
export async function resolveOwnershipHandover(
  id: string,
  orgId: OrgId,
  status: Exclude<OwnershipHandoverStatus, "pending" | "expired">,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt })
    .where(
      and(
        eq(ownershipHandovers.id, id),
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .returning()
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/**
 * Withdraws every still-open offer that names `userId` as either party.
 * A lapsed offer is not open and is left untouched.
 */
export async function cancelOpenOwnershipHandoversForUser(
  orgId: OrgId,
  userId: UserId,
  resolvedAt: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt })
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, resolvedAt),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}
